from __future__ import annotations

import json
from pathlib import Path
import numpy as np
from scipy import signal
from app.analysis_v2 import analyze_array
from app.audio_core import ensure_pcm_wav, load_audio, write_audio
from app.storage import materialize_input, publish_files


def _repair_clicks(audio: np.ndarray, sensitivity: float = 12.0) -> tuple[np.ndarray, dict]:
    repaired=audio.copy(); total=0
    for channel in range(audio.shape[1]):
        derivative=np.diff(repaired[:,channel],prepend=repaired[0,channel]); median=float(np.median(derivative)); mad=float(np.median(np.abs(derivative-median))+1e-9); indices=np.flatnonzero(np.abs(derivative-median)>sensitivity*mad); indices=indices[(indices>2)&(indices<len(audio)-3)]
        for index in indices: repaired[index-1:index+2,channel]=np.linspace(repaired[index-2,channel],repaired[index+2,channel],3)
        total+=int(len(indices))
    return repaired,{"click_candidates_repaired":total,"sensitivity":sensitivity}


def _notch_hum(audio: np.ndarray,sample_rate:int,frequency:float,harmonics:int=4)->np.ndarray:
    output=audio
    for harmonic in range(1,harmonics+1):
        target=frequency*harmonic
        if target>=sample_rate/2.0-20: break
        b,a=signal.iirnotch(target,Q=35.0,fs=sample_rate); output=signal.filtfilt(b,a,output,axis=0).astype(np.float32)
    return output


def _harshness_control(audio:np.ndarray,sample_rate:int,amount_db:float)->np.ndarray:
    if amount_db<=0:return audio
    cutoff=min(5200.0,sample_rate/2.0-500.0); sos=signal.butter(2,cutoff,btype="highpass",fs=sample_rate,output="sos"); high=signal.sosfiltfilt(sos,audio,axis=0); return (audio-high+high*10.0**(-amount_db/20.0)).astype(np.float32)


def _detect_narrow_ridges(audio:np.ndarray,sample_rate:int)->list[dict]:
    mono=np.mean(audio,axis=1); freqs,psd=signal.welch(mono,sample_rate,nperseg=min(32768,len(mono))); mask=(freqs>=1500.0)&(freqs<=min(14000.0,sample_rate/2.0))
    if not np.any(mask):return []
    local_psd=10.0*np.log10(psd[mask]+1e-20); local_freqs=freqs[mask]; baseline=signal.medfilt(local_psd,kernel_size=31); peaks,properties=signal.find_peaks(local_psd-baseline,height=8.0,distance=10)
    return [{"frequency_hz":round(float(local_freqs[i]),1),"prominence_db":round(float(h),2)} for i,h in zip(peaks[:8],properties.get("peak_heights",[])[:8])]


def repair_audio_job(payload:dict)->dict:
    artist=str(payload.get("artist") or "sounddecay"); song=str(payload.get("song") or "untitled"); job_dir=Path("/tmp/stemforge_repair_v2"); job_dir.mkdir(parents=True,exist_ok=True); source_path=materialize_input(payload,"audio",job_dir/"source"); pcm=ensure_pcm_wav(source_path,job_dir/"source.wav"); source,sample_rate=load_audio(pcm); before=analyze_array(source,sample_rate); ridges=_detect_narrow_ridges(source,sample_rate); processed=source.copy(); operations=[]
    if bool(payload.get("declick",True)): processed,click_report=_repair_clicks(processed,sensitivity=float(payload.get("click_sensitivity",14.0))); operations.append({"operation":"declick",**click_report})
    hum=payload.get("hum_frequency_hz")
    if hum in (50,50.0,60,60.0): processed=_notch_hum(processed,sample_rate,float(hum)); operations.append({"operation":"hum_notch","frequency_hz":float(hum),"harmonics":4})
    harshness=float(payload.get("harshness_reduction_db",0.0))
    if harshness>0: processed=_harshness_control(processed,sample_rate,min(harshness,3.0)); operations.append({"operation":"gentle_high_band_reduction","amount_db":min(harshness,3.0)})
    output_path=job_dir/f"{song.replace(' ','_')}_repaired.wav"; write_audio(output_path,processed,sample_rate); report={"status":"completed","engine":"StemForge conservative repair engine v2","operations":operations,"detected_narrow_spectral_ridges":ridges,"before":before,"after":analyze_array(processed,sample_rate),"honesty_note":"Repair is intentionally conservative. Spectral-ridge detection is diagnostic and does not identify whether audio was generated by AI."}; report_path=job_dir/"repair_report.json"; report_path.write_text(json.dumps(report,indent=2),encoding="utf-8"); report["outputs"]=publish_files([output_path,report_path],artist=artist,category="repairs",ttl_seconds=int(payload.get("output_ttl_seconds",86400))); return report


def humanize_audio_job(payload:dict)->dict:
    artist=str(payload.get("artist") or "sounddecay"); song=str(payload.get("song") or "untitled"); role=str(payload.get("role") or "instrument").lower()
    if role in {"lead_vocal","vocal","vocals"} and not bool(payload.get("allow_vocal_processing",False)): return {"status":"rejected","reason":"Lead-vocal humanization is disabled by default to honor the no-vocal-time-warping rule. Set allow_vocal_processing=true only for micro-dynamics without timing changes."}
    job_dir=Path("/tmp/stemforge_humanize_v2"); job_dir.mkdir(parents=True,exist_ok=True); source_path=materialize_input(payload,"audio",job_dir/"source"); pcm=ensure_pcm_wav(source_path,job_dir/"source.wav"); source,sample_rate=load_audio(pcm); seed=int(payload.get("seed",1606)); rng=np.random.default_rng(seed); duration=len(source)/sample_rate; control_count=max(3,int(duration*2.0)+1); points=rng.normal(0.0,float(payload.get("microdynamics_db",0.18)),control_count); window=min(control_count//2*2+1,21)
    if window>=3: points=signal.savgol_filter(points,window,2)
    gain_db=np.interp(np.arange(len(source))/sample_rate,np.linspace(0.0,duration,control_count),points); processed=source*(10.0**(gain_db/20.0))[:,None]; envelope=np.abs(signal.hilbert(np.mean(source,axis=1))); novelty=np.maximum(0.0,np.diff(envelope,prepend=envelope[0])); transients=novelty>np.quantile(novelty,0.995); variation=rng.normal(0.0,float(payload.get("transient_variation",0.015)),len(source)); variation=signal.savgol_filter(variation,101,2); processed*=1.0+transients[:,None]*variation[:,None]; maximum=float(np.max(np.abs(processed))+1e-12)
    if maximum>0.98: processed*=0.98/maximum
    output_path=job_dir/f"{song.replace(' ','_')}_{role}_humanized.wav"; write_audio(output_path,processed,sample_rate); report={"status":"completed","engine":"StemForge deterministic performance naturalization v2","role":role,"seed":seed,"time_warping_applied":False,"pitch_correction_applied":False,"operations":["slow phrase-level microdynamics","subtle transient-strength variation","length-preserving peak safety"],"before":analyze_array(source,sample_rate),"after":analyze_array(processed,sample_rate)}; report_path=job_dir/"humanize_report.json"; report_path.write_text(json.dumps(report,indent=2),encoding="utf-8"); report["outputs"]=publish_files([output_path,report_path],artist=artist,category="humanized",ttl_seconds=int(payload.get("output_ttl_seconds",86400))); return report
